import { beforeEach, describe, it } from 'vitest';
import { supabase } from '@/lib/supabase';
import { appendChangeLog } from './repo';
import { mock } from 'jest-mock-extended';

const mockSupabase = mock<ReturnType<typeof import('@/lib/supabase')>>();
mockSupabase.from.mockReturnThis();
mockSupabase.from().insert.mockResolvedValue({ data: null, error: null });

describe('appendChangeLog', () => {
  beforeEach(() => {
    jest.resetAllMocks();
    supabase = mockSupabase;
  });

  it('should insert without id key', async () => {
    await appendChangeLog({ user_id: '1', table: 'library', action: 'create', payload: { name: 'test' } });
