      table: 'library',
      action: 'create',
      payload: { name: 'test' },
      user_id: '1',
      timestamp: expect.any(Date)
    }]);
  });

  it('should propagate errors', async () => {
    mockSupabase.from().insert.mockRejectedValue(new Error('Database error'));
    await expect(appendChangeLog({ user_id: '1', table: 'library', action: 'create', payload: { name: 'test' } })).rejects.toThrow('Database error');
  });
});

